def count_vowels(s, count_long=0):
    count = 0
    vowel_count = 0

    for i in range(len(s)):
        if s[i].lower() in ['a', 'e', 'i', 'o', 'u']:
            count += 1
            consonant = s[i]

            if count >= count_long and len(consonant) > 1:
                vowel_count += (count_long - 1) * 2
                count = 0
            elif count_long > 0:
                vowel_count += count_long

        else:
            count = 0

    return vowel_count


