def count_vowels(s):
    s = s.strip(".,?!;()[]-_=+/\".:;#").lower()
    if len(s) == 0:
        return 0
    elif s[0] in ['a', 'e', 'i', 'o', 'u']:
        return 1 + count_vowels(s[1:])
    else:
        return count_vowels(s[1:])

